    act_comp = h['result']['composite']
    losses, pred_comp = simulate(h['args']['N'], h['args']['D'], h['args']['mix'], h['args'].get('pool'))
    comp_diffs.append(act_comp - pred_comp)

comp_diffs = np.array(comp_diffs)
